    h[2*j + 1] = A->imagp[j*IA];
}

// Perform Discrete Fourier Transform.
for (k = 0; k < N; ++k)
    H[k] = scale *
        sum(h[j] * e**(-Direction*2*pi*i*j*k/N), 0 <= j < N);

// Pack DC and Nyquist components into C->realp[0] and C->imagp[0].
